#include "openconsole/publisher_keys.h"
#include "openconsole/sha256.h"
static uint32_t u32(const uint8_t*p){return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}
static uint64_t u64(const uint8_t*p){uint64_t v=0;unsigned i;for(i=0;i<8;i++)v|=(uint64_t)p[i]<<(i*8);return v;}
static int eq(const uint8_t*a,const uint8_t*b,size_t n){uint8_t d=0;while(n--)d|=*a++^*b++;return d==0;}
static int id(const uint8_t*p,size_t n){size_t i;if(!n||n>64||!((p[0]>='a'&&p[0]<='z')||(p[0]>='0'&&p[0]<='9')))return 0;for(i=1;i<n;i++)if(!((p[i]>='a'&&p[i]<='z')||(p[i]>='0'&&p[i]<='9')||p[i]=='_'||p[i]=='-'))return 0;return 1;}
static int record(const oc_publisher_key_store*s,size_t at,oc_publisher_key*r,size_t*next){uint8_t il,nl;if(at>s->size||104u>s->size-at)return 0;il=s->blob[at+94];nl=s->blob[at+95];if((size_t)il+nl>s->size-at-104u)return 0;r->key_id=s->blob+at;r->public_key=s->blob+at+32;r->scopes=u32(s->blob+at+89);r->state=s->blob[at+93];r->publisher_id=s->blob+at+104;r->publisher_id_size=il;r->display_name=r->publisher_id+il;r->display_name_size=nl;*next=at+104u+il+nl;return 1;}
oc_publisher_keys_result oc_publisher_keys_parse(const uint8_t*b,size_t n,oc_publisher_key_store*s){uint8_t d[32];uint32_t count,rlen;uint64_t total;size_t at=64,i,j,next;oc_publisher_key r,prior;if(!b||!s||n<64)return OC_PUBLISHER_KEYS_TRUNCATED;if(!eq(b,(const uint8_t*)"OCPK",4))return OC_PUBLISHER_KEYS_MAGIC;if(b[4]!=1||b[5]||b[6]||b[7])return OC_PUBLISHER_KEYS_VERSION;count=u32(b+12);rlen=u32(b+16);total=u64(b+24);if(u32(b+8)!=64||count>256||rlen>65536||u32(b+20)||total!=n||total!=64u+rlen)return OC_PUBLISHER_KEYS_HEADER;if(!oc_sha256(b+64,rlen,d)||!eq(d,b+32,32))return OC_PUBLISHER_KEYS_DIGEST;s->blob=b;s->size=n;s->count=count;for(i=0;i<count;i++){s->offsets[i]=at;if(!record(s,at,&r,&next))return OC_PUBLISHER_KEYS_TRUNCATED;if(r.scopes!=1u||(r.state!=1u&&r.state!=2u)||!id(r.publisher_id,r.publisher_id_size)||!r.display_name_size||r.display_name_size>64)return OC_PUBLISHER_KEYS_RECORD;for(j=0;j<8;j++)if(b[at+96+j])return OC_PUBLISHER_KEYS_RECORD;for(j=0;j<r.display_name_size;j++)if(r.display_name[j]<32||r.display_name[j]>126)return OC_PUBLISHER_KEYS_RECORD;if(!oc_sha256(r.public_key,57,d)||!eq(d,r.key_id,32))return OC_PUBLISHER_KEYS_RECORD;if(i){int cmp=0;for(j=0;j<32;j++)if(r.key_id[j]!=prior.key_id[j]){cmp=r.key_id[j]>prior.key_id[j]?1:-1;break;}if(cmp<=0)return OC_PUBLISHER_KEYS_RECORD;}prior=r;at=next;}return at==n?OC_PUBLISHER_KEYS_OK:OC_PUBLISHER_KEYS_HEADER;}
oc_publisher_keys_result oc_publisher_keys_find_game_signing(const oc_publisher_key_store*s,const uint8_t kid[32],oc_publisher_key*out){size_t i,next;if(!s||!kid||!out)return OC_PUBLISHER_KEYS_NOT_FOUND;for(i=0;i<s->count;i++){if(!record(s,s->offsets[i],out,&next))return OC_PUBLISHER_KEYS_RECORD;if(eq(out->key_id,kid,32)){if(out->state==2)return OC_PUBLISHER_KEYS_REVOKED;return (out->scopes&1u)?OC_PUBLISHER_KEYS_OK:OC_PUBLISHER_KEYS_NOT_FOUND;}}return OC_PUBLISHER_KEYS_NOT_FOUND;}
const char*oc_publisher_keys_result_code(oc_publisher_keys_result r){static const char*const n[]={"OCPK_OK","OCPK_TRUNCATED","OCPK_BAD_MAGIC","OCPK_UNSUPPORTED_VERSION","OCPK_BAD_HEADER","OCPK_DIGEST","OCPK_BAD_RECORD","OCPK_NOT_FOUND","OCPK_REVOKED"};return (unsigned)r<sizeof(n)/sizeof(n[0])?n[r]:"OCPK_UNKNOWN";}
